\set ON_ERROR_STOP on
begin;
with d as (select id, insurance_company_id from program_document where id::text like '93b76c4c%')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl from d cross join (values
('общие-исключения','народная медицина гомеопатия гирудотерапия увт остеопатия кинезиотейпирование вытяжение','excluded','кроме пневмомассажа барабанных перепонок','п. 11.23.2.4'),
('амбулатория-манипуляции','оперативное лечение проктология пункции массаж простаты внутрисуставные введения радиоволновой скальпель','excluded','включая операции в дневном стационаре под общей анестезией и льготные рецепты','п. 11.23.2.5'),
('диагностика','кт мскт мрт пэт сцинтиграфия маммография эндоскопия узи-допплер холтер велоэргометрия','excluded','кроме случаев, прямо предусмотренных Программой страхования','п. 11.23.2.6'),
('диагностика','онкомаркеры гормональные пцр аллергодиагностика иммунный статус коагулограмма витамины микроэлементы','excluded',null,'п. 11.23.2.7'),
('общие-исключения','планирование семьи бесплодие эко импотенция вмс сексуальные расстройства','excluded','кроме удаления ВМС при жизнеугрожающих состояниях','п. 11.23.2.8'),
('общие-исключения','беременность после установления факта роды послеродовой период лактостаз','excluded','прерывание беременности по медицинским показаниям может быть предусмотрено Программой','п. 11.23.2.9'),
('документы-справки','выдача медицинской документации диспансеризация справки для мсэк прав оружия кредита','excluded','кроме справки 095/у, листка нетрудоспособности и документов по результатам услуг Программы','п. 11.23.2.10'),
('общие-исключения','эстетические косметические процедуры удаление невусов папиллом липом коррекция веса','excluded',null,'п. 11.23.2.11'),
('общие-исключения','офтальмологические аппаратные методы лечение близорукости лазерная коагуляция френулотомия фимоз','excluded',null,'п. 11.23.2.12'),
('стационар','дневной стационар плановые инфузии подготовка к плановой госпитализации','excluded','если у застрахованного нет Программы с плановой стационарной помощью','п. 11.23.2.20'),
('общие-условия','нарушение порядка получения услуг без предварительного согласования','excluded','если согласование со Страховщиком предусмотрено Программой или договором','п. 11.23.2.21'),
('общие-условия','услуги до или после окончания срока страхования','excluded','кроме стационарного лечения при госпитализации в срок договора — до выписки','п. 11.23.2.22'),
('лекарства','лекарства очки линзы слуховые аппараты корсеты костыли компрессионный трикотаж','excluded',null,'п. 11.23.2.23'),
('протезирование','медицинские изделия имплантируемые в организм','excluded',null,'п. 11.23.2.24')
) as v(sc, sp, vd, ct, cl);
select count(*) as ing2306 from coverage_rule where document_id = (select id from program_document where id::text like '93b76c4c%');
commit;
